function lengthOfLastWord(s: string): number {
  let i = s.length - 1;

  // Пропускаем пробелы в конце строки
  while (i >= 0 && s[i] === ' ') {
    i--;
  }

  // Считаем символы последнего слова, пока не встретим пробел или начало строки
  let length = 0;
  while (i >= 0 && s[i] !== ' ') {
    length++;
    i--;
  }

  return length;
}

// Время: O(n) в худшем случае, но смотрим только хвост строки
// Память: O(1) — без split и новых строк
